using System;
using System.Linq;
namespace F1Manager {
public static class ResearchTests {
    static string Decisions(Team team){return team.NextResearchDay+"/"+team.ResearchSpent.ToString("0.00")+"/"+string.Join(";",team.Parts.Select(p=>p.Key+":"+p.Version+":"+p.Bonus.ToString("0.000000")).Concat(team.NextParts.Select(p=>"next:"+p.Key+":"+p.Version+":"+p.Bonus.ToString("0.000000"))).Concat(team.Projects.Select(p=>p.Key+":"+p.TargetYear+":"+p.Start+":"+p.DesignEnd+":"+p.Due+":"+p.Engineers+":"+p.Gain+":"+p.Failed)));}
    public static void Run(Action<bool,string> check,Action<Action,string> rejects){
        var early=Data.Create(0,"",442);string original=Engine.Serialize(early);rejects(()=>Engine.Develop(early,"floor",4,true),"next-year research is locked before the summer milestone");check(Engine.Serialize(early)==original,"locked next-year research does not charge money or allocate engineers");
        var future=Data.Create(-1,"Future",443);Engine.Advance(future,Research.UnlockDay);check(Research.NextYearOpen(future),"next-year development unlocks at the documented day");var player=Engine.Team(future,future.Player);player.Parts.Add(new Installed{Key="front",Bonus=8});var before=CarModel.Values(player);double cash=future.Cash;Engine.Develop(future,"floor",4,true);var project=player.Projects.Single();project.Failure=0;check(project.TargetYear==2027&&future.Spent==project.Cost&&future.Cash==cash-project.Cost,"next-year research spends the current cash and shared annual cap");Engine.Develop(future,"front",6);check(Engine.Assigned(future,player)==10&&player.Projects.Count==2,"current and future projects share engineer and slot capacity");rejects(()=>Engine.Develop(future,"rear",1,true),"next-year projects cannot bypass occupied slots");player.Projects.RemoveAll(p=>p.TargetYear==future.Year);Engine.Advance(future,project.Due);check(player.NextParts.Count==1&&!player.Parts.Any(p=>p.Key=="floor")&&CarModel.Values(player).SequenceEqual(before),"completed next-year floor is stored without improving the current car");Engineering.CompleteRound(future);check(future.EngineeringReports.Last().Upgrades.Count==0&&future.UpgradeTrials.Single().Year==2027&&!future.UpgradeTrials.Single().Reported,"future upgrades are not falsely validated in this year's race report");
        var saved=Engine.Deserialize(Engine.Serialize(future));check(Engine.Team(saved,saved.Player).NextParts.Count==1&&Math.Abs(saved.Spent-future.Spent)<.00001,"future parts, target years and shared spending survive save/load");double gain=player.NextParts[0].Bonus;future.SeasonDone=true;Engine.NextSeason(future);check(player.NextParts.Count==0&&Math.Abs(player.Parts.Single(p=>p.Key=="floor").Bonus-gain)<.00001,"prepared next-year parts retain their full gain on the new car");check(Math.Abs(player.Parts.Single(p=>p.Key=="front").Bonus-8*Research.Carryover)<.00001,"previous-year components retain only 65 percent of their gain");check(future.Spent==0&&future.UpgradeTrials.Single().Delta.Any(v=>v>0),"new year resets annual cap and computes actual adopted upgrade effects");Engineering.CompleteRound(future);check(future.EngineeringReports.Last().Upgrades.Count==1&&future.EngineeringReports.Last().Upgrades[0].Reported,"adopted next-year upgrade is evaluated in the new season");
        var carry=Data.Create(0,"",448);Engine.Advance(carry,280);Engine.Develop(carry,"floor",3);var carried=Engine.Team(carry,0).Projects.Single();carried.Failure=0;double plannedGain=carried.Gain;carry.SeasonDone=true;Engine.NextSeason(carry);check(Math.Abs(carried.Gain-plannedGain*Research.Carryover)<.00001,"unfinished current-year designs also lose efficiency at season rollover");
        var cap=Data.Create(0,"",444);Engine.Advance(cap,Research.UnlockDay);cap.Spent=94;rejects(()=>Engine.Develop(cap,"floor",4,true),"future research cannot bypass the current season's 95 million cap");
        var rivals=Data.Create(0,"",445);foreach(var t in rivals.Teams){t.Base=Enumerable.Repeat(72.0,6).ToArray();t.EngineRating=80;t.EngineReliability=85;}double ownScore=CarModel.Score(Engine.Team(rivals,0),Data.Tracks[5]);var baselines=rivals.Teams.Select(t=>(double[])t.Base.Clone()).ToArray();Research.PlanDay(rivals);check(rivals.Teams.Where(t=>t.Id!=rivals.Player).All(t=>t.Projects.Count>0&&t.ResearchSpent>0),"all rival teams independently start funded development projects");int active=rivals.Teams.Sum(t=>t.Projects.Count);Research.PlanDay(rivals);check(active==rivals.Teams.Sum(t=>t.Projects.Count),"repeated processing of the same day does not duplicate AI projects");Engine.Advance(rivals,120);check(rivals.Teams.Where(t=>t.Id!=rivals.Player).All(t=>t.Parts.Any(p=>p.Bonus>0)),"every rival delivers real component improvements during the season");check(rivals.Teams.Select((t,i)=>t.Base.SequenceEqual(baselines[i])).All(v=>v),"AI development installs components rather than granting hidden base-stat increases");check(rivals.Teams.Where(t=>t.Id!=rivals.Player).All(t=>t.ResearchSpent<=95&&t.Projects.Count<=Engine.Slots(t)&&Engine.Assigned(rivals,t)<=Engine.Capacity(t)),"AI respects the same spending, project and workforce limits as the player");check(CarModel.Score(Engine.Team(rivals,0),Data.Tracks[5])==ownScore&&CarModel.TrackRank(rivals,Data.Tracks[5])>1,"unchanged player components lose relative competitiveness as opponents develop");check(!Engine.Team(rivals,0).Parts.Any()&&rivals.Spent==0,"AI does not develop the player's car or spend the player's money");
        var replay=Engine.Deserialize(Engine.Serialize(rivals));Engine.Advance(rivals,260);Engine.Advance(replay,260);check(rivals.Seed==replay.Seed&&rivals.Teams.Select(Decisions).SequenceEqual(replay.Teams.Select(Decisions)),"AI decisions and deliveries remain deterministic across save/reload");check(rivals.Teams.Where(t=>t.Id!=rivals.Player).Any(t=>t.NextParts.Count>0||t.Projects.Any(p=>p.TargetYear==2027)),"AI allocates part of the shared budget to the following season");
        var migration=Data.Create(0,"",446);migration.Version=4;foreach(var t in migration.Teams)t.NextParts=null;uint seed=migration.Seed;var updated=Engine.Deserialize(Engine.Serialize(migration));check(updated.Version==7&&updated.Seed==seed&&updated.Teams.All(t=>t.NextParts!=null),"schema 4 migration initializes AI and future inventories without consuming random state");Engine.Team(updated,0).Projects.Add(new Project{Key="floor",Engineers=2,TargetYear=2030});rejects(()=>Engine.Validate(updated),"invalid project target year is rejected");
    }
}
}
